fn reverse(a: &Vec<char>) -> Vec<char> {
    // Pre-allocate a vector with the same length as `a`
    let mut b = Vec::with_capacity(a.len());
    // Iterate `a` in reverse order, pushing each character into `b`
    for &c in a.iter().rev() {
        b.push(c);
    }
    b
}

fn main() {
    let input: Vec<char> = "hello".chars().collect();
    let output = reverse(&input);
    let result: String = output.into_iter().collect();
    println!("{}", result); // prints "olleh"
}